"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3362],{59839:t=>{t.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"HighlightedPrompt","desc":"Wraps a ProximityPrompt with a Highlight effect and a\\nBillboardGui button (tap on mobile, keybind on desktop).\\n\\nBy default, the highlight + billboard auto-toggle on\\n`PromptShown` / `PromptHidden` (proximity-driven). Pass\\n`HighlightOnProximity = false` to disable this and drive\\nvisibility manually via `prompt:SetHovered(visible)`.\\n\\nAPI:\\n  local prompt = HighlightedPrompt.new(instance, { ObjectText = \\"Grab\\" })\\n  prompt.Triggered:Connect(function() ... end)\\n  prompt:SetObjectText(\\"Item\\")\\n  prompt:SetActionText(\\"Drop\\")\\n  prompt:SetHovered(true)   -- manual mode only\\n  prompt:Destroy()","source":{"line":23,"path":"src/Shared/Class/HighlightedPrompt.luau"}}')}}]);